1	import { Server as SocketIOServer } from "socket.io";
2	import type { Server as HttpServer } from "node:http";
3	import { clerkClient } from "@clerk/express";
4	import { and, eq } from "drizzle-orm";
5	import {
6	  db,
7	  courtsTable,
8	  facilitiesTable,
9	  gamesTable,
10	  gameParticipantsTable,
11	} from "@workspace/db";
12	import { logger } from "./logger";
13	
14	// Authorization helpers for narrow chat rooms. Both must run before a
15	// socket is joined, otherwise any authenticated user could `join_rooms`
16	// with arbitrary IDs and silently eavesdrop on other users' chats.
17	
18	async function canJoinFacilityRoom(userId: string, courtId: number, playerId: string): Promise<boolean> {
19	  // The player half of the conversation is always allowed.
20	  if (userId === playerId) return true;
21	  // The court owner is the other legitimate participant.
22	  const [row] = await db
23	    .select({ ownerUserId: facilitiesTable.ownerUserId })
24	    .from(courtsTable)
25	    .innerJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
26	    .where(eq(courtsTable.id, courtId))
27	    .limit(1);
28	  return row?.ownerUserId === userId;
29	}
30	
31	async function canJoinGameRoom(userId: string, gameId: number): Promise<boolean> {
32	  const [creator] = await db
33	    .select({ creatorUserId: gamesTable.creatorUserId })
34	    .from(gamesTable)
35	    .where(eq(gamesTable.id, gameId))
36	    .limit(1);
37	  if (creator?.creatorUserId === userId) return true;
38	  const [participant] = await db
39	    .select({ id: gameParticipantsTable.id })
40	    .from(gameParticipantsTable)
41	    .where(and(
42	      eq(gameParticipantsTable.gameId, gameId),
43	      eq(gameParticipantsTable.userId, userId),
44	      eq(gameParticipantsTable.status, "joined"),
45	    ))
46	    .limit(1);
47	  return !!participant;
48	}
