1	import { Router, type IRouter } from "express";
2	import { eq, and, desc, inArray, or, isNull } from "drizzle-orm";
3	import { db, coachesTable, courtCoachesTable, courtCoachInvitationsTable, courtsTable, facilitiesTable } from "@workspace/db";
4	import { requireAuth, getCurrentUserId, isOwner, getUserRole, requireCoach, requireOwner } from "../lib/auth";
5	import { sendNotification } from "../lib/notify";
6	import { sendCoachInviteEmail } from "../lib/email";
7	import { z } from "zod";
8	import { EmailString, OptionalEmailString, OptionalPhoneString } from "@workspace/api-zod";
