10	const CoachUpsertBody = z.object({
11	  name: z.string().trim().min(2, "Vardas privalomas"),
12	  email: EmailString,
13	  bio: z.string().optional().nullable(),
14	  photoUrl: z.string().optional().nullable(),
15	  videoUrl: z.string().optional().nullable(),
16	  // Integer cents — clients must multiply euros × 100 before submitting.
17	  // Coerce from string so old form fields that produce "2500" still work.
18	  pricePerHour: z.coerce.number().int().nonnegative().optional().nullable(),
19	  sports: z.array(z.string()).optional(),
20	  availabilityDescription: z.string().optional().nullable(),
21	  phone: OptionalPhoneString,
22	  isAcceptingStudents: z.boolean().optional(),
23	  experienceYears: z.coerce.number().int().nonnegative().optional().nullable(),
24	});
25	
26	const CoachInviteBody = z.object({
27	  targetUserId: z.string().optional(),
28	  targetEmail: OptionalEmailString,
29	  targetName: z.string().optional(),
30	}).refine(d => d.targetUserId || d.targetEmail, {
31	  message: "Reikia targetUserId arba targetEmail",
