34	async function getCourtOwnerUserId(facilityId: number): Promise<string | null> {
35	  const [f] = await db.select({ ownerUserId: facilitiesTable.ownerUserId })
36	    .from(facilitiesTable)
37	    .where(eq(facilitiesTable.id, facilityId));
38	  return f?.ownerUserId ?? null;
