47	const router: IRouter = Router();
48	
49	function formatCoach(c: typeof coachesTable.$inferSelect) {
50	  return {
51	    ...c,
52	    // pricePerHour is integer cents — clients divide by 100 for display.
53	    bio: c.bio ?? undefined,
54	    photoUrl: c.photoUrl ?? undefined,
55	    videoUrl: c.videoUrl ?? undefined,
56	    availabilityDescription: c.availabilityDescription ?? undefined,
57	    phone: c.phone ?? undefined,
58	    experienceYears: c.experienceYears ?? undefined,
59	    createdAt: c.createdAt.toISOString(),
60	  };
61	}
62	
63	function formatPublicCoach(c: typeof coachesTable.$inferSelect) {
64	  return {
65	    id: c.id,
66	    userId: c.userId,
67	    name: c.name,
68	    bio: c.bio ?? undefined,
69	    photoUrl: c.photoUrl ?? undefined,
70	    videoUrl: c.videoUrl ?? undefined,
71	    pricePerHour: c.pricePerHour ?? undefined,
72	    sports: c.sports,
73	    availabilityDescription: c.availabilityDescription ?? undefined,
74	    isAcceptingStudents: c.isAcceptingStudents,
75	    experienceYears: c.experienceYears ?? undefined,
76	    createdAt: c.createdAt.toISOString(),
77	  };
78	}
