80	// GET /coaches — list approved coaches, or filter by courtId. Each coach is
81	// enriched with `cities: string[]` from the courts/facilities they teach at.
82	router.get("/coaches", async (req, res): Promise<void> => {
83	  const courtId = req.query.courtId ? parseInt(req.query.courtId as string, 10) : null;
84	
85	  let coaches: Array<typeof coachesTable.$inferSelect>;
86	  if (courtId !== null && !isNaN(courtId)) {
87	    const rows = await db
88	      .select({ coach: coachesTable })
89	      .from(courtCoachesTable)
90	      .innerJoin(coachesTable, eq(courtCoachesTable.coachId, coachesTable.id))
91	      .where(and(eq(courtCoachesTable.courtId, courtId), eq(coachesTable.status, "approved")));
92	    coaches = rows.map(r => r.coach);
93	  } else {
94	    coaches = await db
95	      .select()
96	      .from(coachesTable)
97	      .where(eq(coachesTable.status, "approved"))
98	      .orderBy(coachesTable.createdAt);
99	  }
100	
101	  if (coaches.length === 0) { res.json([]); return; }
102	
103	  const cityRows = await db
104	    .select({
105	      coachId: courtCoachesTable.coachId,
106	      facilityCity: facilitiesTable.city,
107	    })
108	    .from(courtCoachesTable)
109	    .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
110	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
111	    .where(inArray(courtCoachesTable.coachId, coaches.map(c => c.id)));
112	
113	  const citiesByCoach = new Map<number, Set<string>>();
114	  for (const row of cityRows) {
115	    const c = row.facilityCity;
116	    if (!c) continue;
117	    if (!citiesByCoach.has(row.coachId)) citiesByCoach.set(row.coachId, new Set());
118	    citiesByCoach.get(row.coachId)!.add(c);
119	  }
120	
121	  res.json(coaches.map(c => ({
122	    ...formatPublicCoach(c),
123	    cities: Array.from(citiesByCoach.get(c.id) ?? []),
124	  })));
125	});
