150	// GET /coaches/:id/facilities — public list of facilities/courts a coach is approved at.
151	// Only publicly-visible courts (status approved/active) and verified facilities are returned.
152	router.get("/coaches/:id/facilities", async (req, res): Promise<void> => {
153	  const id = parseInt(String(req.params.id), 10);
154	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
155	  const [coach] = await db.select().from(coachesTable)
156	    .where(and(eq(coachesTable.id, id), eq(coachesTable.status, "approved")));
157	  if (!coach) { res.json([]); return; }
158	
159	  const rows = await db
160	    .select({ court: courtsTable, facility: facilitiesTable })
161	    .from(courtCoachesTable)
162	    .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
163	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
164	    .where(and(
165	      eq(courtCoachesTable.coachId, id),
166	      inArray(courtsTable.status, ["approved", "active"]),
167	      // If court is in a facility, that facility must be verified.
168	      // Standalone courts (no facility) pass this check via the OR.
169	      or(
170	        isNull(courtsTable.facilityId),
171	        eq(facilitiesTable.verificationStatus, "active"),
172	      )!,
173	    ));
174	
175	  type Group = {
176	    facilityId: number | null;
177	    facilityName: string | null;
178	    city: string | null;
179	    address: string | null;
180	    courts: Array<{ id: number; name: string }>;
181	  };
182	  const groups = new Map<string, Group>();
183	  for (const r of rows) {
184	    const key = r.facility?.id != null ? `f${r.facility.id}` : `c${r.court.id}`;
185	    if (!groups.has(key)) {
186	      groups.set(key, {
187	        facilityId: r.facility?.id ?? null,
188	        facilityName: r.facility?.name ?? r.court.name,
189	        city: r.facility?.city ?? null,
190	        address: r.facility?.address ?? null,
191	        courts: [],
192	      });
193	    }
194	    groups.get(key)!.courts.push({ id: r.court.id, name: r.court.name });
195	  }
196	  res.json(Array.from(groups.values()));
197	});
