748	// POST /owner/respond-to-coach — owner approves or rejects a pending coach request
749	router.post("/owner/respond-to-coach", requireOwner, async (req, res): Promise<void> => {
750	  const { invitationId, decision } = req.body ?? {};
751	  const id = Number(invitationId);
752	  if (!Number.isFinite(id)) { res.status(400).json({ error: "invitationId required" }); return; }
753	  if (decision !== "approve" && decision !== "reject") {
754	    res.status(400).json({ error: "decision must be 'approve' or 'reject'" }); return;
755	  }
756	
757	  const [invite] = await db.select().from(courtCoachInvitationsTable)
758	    .where(eq(courtCoachInvitationsTable.id, id));
759	  if (!invite) { res.status(404).json({ error: "Invitation not found" }); return; }
760	
761	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, invite.courtId));
762	  if (!court) { res.status(404).json({ error: "Court not found" }); return; }
763	
764	  const canEdit = await isOwner(req, await getCourtOwnerUserId(court.facilityId));
765	  if (!canEdit) { res.status(403).json({ error: "Forbidden – not the court owner" }); return; }
766	
767	  if (invite.status !== "pending") {
768	    res.status(409).json({ error: `Invitation already ${invite.status}` }); return;
769	  }
770	
771	  await db.update(courtCoachInvitationsTable)
772	    .set({ status: decision === "approve" ? "approved" : "rejected" })
773	    .where(eq(courtCoachInvitationsTable.id, id));
774	
775	  if (decision === "approve" && invite.targetUserId) {
776	    let [coach] = await db.select().from(coachesTable)
777	      .where(eq(coachesTable.userId, invite.targetUserId));
778	    if (!coach) {
779	      [coach] = await db.insert(coachesTable).values({
780	        userId: invite.targetUserId,
781	        name: invite.targetName ?? "Treneris",
782	        email: invite.targetEmail ?? "",
783	        status: "approved",
784	        sports: [],
785	      }).returning();
786	    }
787	    const [existing] = await db.select().from(courtCoachesTable)
788	      .where(and(eq(courtCoachesTable.courtId, court.id), eq(courtCoachesTable.coachId, coach.id)));
789	    if (!existing) {
790	      try {
791	        await db.insert(courtCoachesTable).values({ courtId: court.id, coachId: coach.id });
792	      } catch (err: unknown) {
793	        // Postgres unique_violation (23505) — a concurrent approval already created the link.
794	        // The end state (coach approved on this court) is what we want, so swallow and continue.
795	        const code = (err as { code?: string } | null)?.code;
796	        if (code !== "23505") throw err;
797	      }
798	    }
799	    await sendNotification(invite.targetUserId, "court_coach_approved",
800	      "Paraiška patvirtinta",
801	      `Jūs priimtas kaip treneris į „${court.name}"`,
802	      `/coach/me`,
803	    ).catch(() => {});
804	  } else if (decision === "reject" && invite.targetUserId) {
805	    await sendNotification(invite.targetUserId, "court_coach_rejected",
806	      "Paraiška atmesta",
807	      `Jūsų paraiška „${court.name}" buvo atmesta`,
808	      `/coach/me`,
809	    ).catch(() => {});
810	  }
811	
812	  res.json({ ok: true, status: decision === "approve" ? "approved" : "rejected" });
813	});
