186	      fetchNotifs();
187	      if (isAdmin) fetchAdminNotifs();
188	    }, 2000);
189	    intervalRef.current = setInterval(() => {
190	      fetchNotifs();
191	      if (isAdmin) fetchAdminNotifs();
192	    }, 30000);
193	    return () => {
194	      clearTimeout(delay);
195	      if (intervalRef.current) clearInterval(intervalRef.current);
196	    };
197	  }, [userId, isAdmin, fetchNotifs, fetchAdminNotifs]);
198	
199	  async function markRead(notif: Notif) {
200	    const isAdminNotif = notif.userId === "__ADMIN__";
201	    const endpoint = isAdminNotif
202	      ? `/api/admin/notifications/${notif.id}/read`
203	      : `/api/notifications/${notif.id}/read`;
204	
205	    if (isAdminNotif) {
206	      setAdminNotifs(prev => prev.map(n => n.id === notif.id ? { ...n, read: true } : n));
207	    } else {
208	      setNotifs(prev => prev.map(n => n.id === notif.id ? { ...n, read: true } : n));
209	    }
210	    try {
211	      await authFetch(endpoint, { method: "PATCH" });
212	    } catch { /* silent */ }
213	    // Keep the owner-layout sidebar pill in sync — its query derives unread
214	    // count from this same /api/notifications data, so we invalidate it
215	    // whenever a facility-bound message notification gets read.
216	    if (notif.type === "message" && notif.link?.startsWith("/owner/")) {
217	      qc.invalidateQueries({ queryKey: ["owner-facility-msg-unread"] });
218	    }
219	  }
220	
221	  async function markTabAllRead() {
222	    if (!userId) return;
223	    try {
224	      if (activeTab === "owner") {
225	        setNotifs(prev => prev.map(n =>
226	          getNotifAudience(n) === "owner" ? { ...n, read: true } : n
227	        ));
228	        setAdminNotifs(prev => prev.map(n => ({ ...n, read: true })));
229	        const calls: Promise<unknown>[] = [
230	          authFetch(`/api/owner/notifications/read-all`, { method: "POST" }),
231	        ];
232	        if (isAdmin) calls.push(authFetch(`/api/admin/notifications/read-all`, { method: "POST" }));
233	        await Promise.all(calls);
234	      } else {
235	        const unread = tabNotifs.filter(n => !n.read && n.userId !== "__ADMIN__");
236	        setNotifs(prev => {
237	          const ids = new Set(unread.map(n => n.id));
238	          return prev.map(n => ids.has(n.id) ? { ...n, read: true } : n);
239	        });
240	        await Promise.all(
241	          unread.map(n => authFetch(`/api/notifications/${n.id}/read`, { method: "PATCH" }))
242	        );
243	      }
244	    } catch { /* silent */ }
245	    // Bulk-read may have cleared facility-bound message notifs — keep the
246	    // owner-layout sidebar pill in sync.
247	    qc.invalidateQueries({ queryKey: ["owner-facility-msg-unread"] });
248	  }
