263	  const stripeMap = new Map(profiles.map(p => [p.userId, p.stripeAccountStatus ?? "not_connected"]));
264	
265	  const enriched = rows.map(r => ({
266	    ...r,
267	    name: clerkUsers[r.userId]?.name ?? null,
