447	/** POST /admin/seed-courts — seed courts from JSON file if DB is empty */
448	router.post("/admin/seed-courts", requireAdmin, async (_req, res): Promise<void> => {
449	  try {
450	    const [{ value: courtCount }] = await db.select({ value: count() }).from(courtsTable);
451	    if (Number(courtCount) > 0) {
452	      res.json({ message: `Skipped — ${courtCount} courts already exist`, inserted: 0 });
453	      return;
454	    }
455	
456	    const seedPath = join(__dirname, "data/courts-seed.json");
457	    const seedData: Array<Record<string, unknown>> = JSON.parse(readFileSync(seedPath, "utf-8"));
458	
459	    // Ensure a seed facility exists to satisfy the notNull facilityId FK
460	    let seedFacilityId: number;
461	    const [existingFacility] = await db.select({ id: facilitiesTable.id }).from(facilitiesTable).limit(1);
462	    if (existingFacility) {
463	      seedFacilityId = existingFacility.id;
464	    } else {
465	      const [newFacility] = await db.insert(facilitiesTable).values({
466	        name: "Seed Facility",
467	        ownerUserId: "seed",
468	        address: "",
469	        city: "",
470	        verificationStatus: "pending",
471	      }).returning({ id: facilitiesTable.id });
472	      seedFacilityId = newFacility.id;
473	    }
474	
475	    const BATCH = 50;
476	    let inserted = 0;
477	    for (let i = 0; i < seedData.length; i += BATCH) {
478	      const batch = seedData.slice(i, i + BATCH).map((c) => ({
479	        name: c.name as string,
480	        type: c.type as string,
481	        description: c.description as string | null,
482	        pricePerHour: String(c.price_per_hour),
483	        imageUrl: c.image_url as string | null,
484	        amenities: (Array.isArray(c.amenities) ? c.amenities : []) as string[],
485	        isIndoor: (c.is_indoor ?? false) as boolean,
486	        maxPlayers: (c.max_players ?? 4) as number,
487	        surface: c.surface as string | null,
488	        condition: (c.condition ?? "good") as string,
489	        rating: c.rating as number | null,
490	        totalBookings: (c.total_bookings ?? 0) as number,
491	        phone: c.phone as string | null,
492	        status: (c.status ?? "approved") as string,
493	        rejectionReason: c.rejection_reason as string | null,
494	        facilityId: seedFacilityId,
495	      }));
496	      await db.insert(courtsTable).values(batch).onConflictDoNothing();
497	      inserted += batch.length;
498	    }
499	
500	    // Reset the sequence to avoid ID collisions with future inserts
501	    const maxId = Math.max(...seedData.map((c) => Number(c.id)));
502	    await db.execute(sql`SELECT setval(pg_get_serial_sequence('courts', 'id'), ${maxId}, true)`);
503	
504	    res.json({ message: "Courts seeded successfully", inserted });
505	  } catch (err) {
506	    console.error("Seed error:", err);
507	    res.status(500).json({ error: "Seed failed", detail: String(err) });
508	  }
509	});
