1	// One-off migration: convert coaches.price_per_hour from numeric(10,2) euros
2	// to integer cents, and add isAcceptingStudents + experienceYears columns.
3	//
4	// Idempotent: rerunning is safe. Each step inspects information_schema before
5	// applying a change so a partial earlier run won't break a retry.
6	//
7	// Run with: cd lib/db && node migrate-coach-cents.mjs
8	
9	import pg from "pg";
10	
11	const { Client } = pg;
12	if (!process.env.DATABASE_URL) {
13	  console.error("DATABASE_URL missing");
14	  process.exit(1);
15	}
16	
17	const db = new Client({ connectionString: process.env.DATABASE_URL });
18	await db.connect();
19	
20	async function columnInfo(column) {
21	  const { rows } = await db.query(
22	    `SELECT data_type, is_nullable
23	       FROM information_schema.columns
24	      WHERE table_name = 'coaches' AND column_name = $1`,
25	    [column],
26	  );
27	  return rows[0] ?? null;
28	}
29	
30	try {
31	  await db.query("BEGIN");
32	
33	  // 1. price_per_hour: numeric → integer cents (multiply by 100, round).
34	  const priceCol = await columnInfo("price_per_hour");
35	  if (!priceCol) {
36	    console.error("coaches.price_per_hour not found — nothing to migrate");
37	  } else if (priceCol.data_type === "integer") {
38	    console.log("✓ price_per_hour already integer — skipping conversion");
39	  } else {
40	    console.log(`Converting price_per_hour from ${priceCol.data_type} → integer cents`);
41	    await db.query(`
42	      ALTER TABLE coaches
43	        ALTER COLUMN price_per_hour TYPE integer
44	        USING ROUND(COALESCE(price_per_hour, 0) * 100)::integer
45	    `);
46	    console.log("✓ price_per_hour converted");
47	  }
48	
49	  // 2. is_accepting_students: add with default true.
50	  const acceptCol = await columnInfo("is_accepting_students");
51	  if (acceptCol) {
52	    console.log("✓ is_accepting_students already exists — skipping");
53	  } else {
54	    await db.query(`
55	      ALTER TABLE coaches
56	        ADD COLUMN is_accepting_students boolean NOT NULL DEFAULT true
57	    `);
58	    console.log("✓ is_accepting_students added");
59	  }
60	
61	  // 3. experience_years: nullable integer.
62	  const expCol = await columnInfo("experience_years");
63	  if (expCol) {
64	    console.log("✓ experience_years already exists — skipping");
65	  } else {
66	    await db.query(`
67	      ALTER TABLE coaches
68	        ADD COLUMN experience_years integer
69	    `);
70	    console.log("✓ experience_years added");
71	  }
72	
73	  await db.query("COMMIT");
74	  console.log("Migration complete.");
75	} catch (err) {
76	  await db.query("ROLLBACK").catch(() => {});
77	  console.error("Migration failed, rolled back:", err);
78	  process.exit(1);
79	} finally {
80	  await db.end();
81	}
