29	
30	function timeAgo(iso: string) {
31	  const d = new Date(iso);
32	  const diff = Date.now() - d.getTime();
33	  const min = Math.floor(diff / 60_000);
34	  if (min < 1) return "dabar";
35	  if (min < 60) return `${min} min.`;
36	  const h = Math.floor(min / 60);
37	  if (h < 24) return `${h} val.`;
38	  return d.toLocaleDateString("lt-LT", { month: "short", day: "numeric" });
39	}
40	
41	function initials(name: string) {
42	  return name.split(" ").map((n) => n[0]).join("").slice(0, 2).toUpperCase();
43	}
